package com.cpf.core.common.reliability;import com.cpf.core.api.reliability.CpfSelfHealingPolicy;import java.time.*;import java.util.*;import java.util.concurrent.ConcurrentHashMap;/** 무한 자동복구 루프를 막는 bounded self-healing guard입니다. */public final class CpfSelfHealingGuard {private final CpfSelfHealingPolicy policy;private final Map<String,State> states=new ConcurrentHashMap<>();public CpfSelfHealingGuard(CpfSelfHealingPolicy policy){this.policy=Objects.requireNonNull(policy);}public Decision allow(String target,Instant now){State s=states.computeIfAbsent(target,k->new State());s.trim(now.minus(policy.window()));if(s.consecutiveFailures>=policy.maxConsecutiveFailures())return new Decision(false,"consecutive-failure-limit");if(s.lastAction!=null&&s.lastAction.plus(policy.cooldown()).isAfter(now))return new Decision(false,"cooldown");if(s.actions.size()>=policy.maxActionsPerWindow())return new Decision(false,"window-limit");s.actions.addLast(now);s.lastAction=now;return new Decision(true,"allowed");}public void success(String target){State s=states.computeIfAbsent(target,k->new State());s.consecutiveFailures=0;}public void failure(String target){states.computeIfAbsent(target,k->new State()).consecutiveFailures++;}public record Decision(boolean allowed,String reason){}private static final class State{final Deque<Instant> actions=new ArrayDeque<>();int consecutiveFailures;Instant lastAction;void trim(Instant from){while(!actions.isEmpty()&&actions.peekFirst().isBefore(from))actions.removeFirst();}}}